from scipy.stats import contingency as ct
x = np.array([2.1, 3.4, 1.9, 5.6, 4.2, 3.3, 2.8, 6.1, 4.4, 3.9, 2.2, 5.0])
y = np.array([1.8, 2.9, 3.1, 4.7, 5.2, 2.6, 3.0, 5.9, 3.5, 4.1, 2.5, 4.4])
B = np.array(big)

@test
def test_contingency():
    tb = np.array([[10, 12, 5], [11, 9, 14]])
    assert close(ct.expected_freq(tb), ef)
    m = ct.margins(tb)
    assert close(m[0].astype(float), mg0)
    assert close(m[1].astype(float), mg1)
    assert close([ct.association(tb), ct.association(tb, method='tschuprow'), ct.association(tb, method='pearson')], assoc)
    a = np.array([1, 2, 2, 3, 1, 3, 3, 2])
    b = np.array([0, 0, 1, 1, 1, 0, 1, 1])
    assert close(ct.crosstab(a, b).count.astype(float), ctab)
    rr = ct.relative_risk(12, 30, 5, 28)
    ci = rr.confidence_interval(0.9)
    assert close([rr.relative_risk, ci.low, ci.high], rr_)
    out = []
    for t2 in [[[8, 2], [1, 5]], [[10, 12], [11, 9]], [[3, 7], [9, 2]]]:
        o = ct.odds_ratio(t2)
        c1 = o.confidence_interval(0.95)
        c2 = o.confidence_interval(0.9, alternative='less')
        o2 = ct.odds_ratio(t2, kind='sample')
        c3 = o2.confidence_interval()
        out += [o.statistic, c1.low, c1.high, c2.high, o2.statistic, c3.low, c3.high]
    assert close(out, orr, rtol=1e-8)
    out = []
    r = st.somersd(np.round(x), np.round(y))
    out += [r.statistic, r.pvalue]
    r = st.somersd(np.array([[10, 3, 2], [4, 8, 5], [1, 2, 9]]))
    out += [r.statistic, r.pvalue]
    r = st.somersd(np.round(x), np.round(y), alternative='greater')
    out += [r.statistic, r.pvalue]
    assert close(out, sd, rtol=1e-10)
    D = np.array([[1, 2, 3, 4], [2, 1, 4, 3], [1, 3, 2, 4], [2, 3, 1, 4], [1, 2, 4, 3]]).astype(float)
    out = []
    p = st.page_trend_test(D)
    out += [p.statistic, p.pvalue]
    p = st.page_trend_test(D, method='asymptotic')
    out += [p.statistic, p.pvalue]
    p = st.page_trend_test(B[:30].reshape(6, 5))
    out += [p.statistic, p.pvalue]
    p = st.page_trend_test(B[:30].reshape(3, 10))
    out += [p.statistic, p.pvalue]
    assert close(out, pt, rtol=1e-10)
test_contingency()

@test
def test_kde_binned_wtau():
    k = st.gaussian_kde(x)
    pts = np.array([1.0, 2.5, 3.7, 5.0, 7.0])
    got = list(k(pts)) + list(k.logpdf(pts)) + [k.factor, k.integrate_box_1d(2.0, 4.0),
                                                 k.integrate_gaussian(np.array([3.0]), np.array([[0.5]]))]
    assert close(got, kde, rtol=1e-10)
    k2 = st.gaussian_kde(x, bw_method='silverman', weights=y)
    assert close(list(k2(pts)) + [k2.factor, k2.neff], kde2, rtol=1e-10)
    k3 = st.gaussian_kde(np.vstack([x, y]), bw_method=0.4)
    assert close(k3(np.array([[2., 3., 4.], [3., 3.5, 2.]])), kde3, rtol=1e-10)
    out = []
    for s_ in ['mean', 'std', 'median', 'count', 'sum', 'min', 'max']:
        r = st.binned_statistic(x, y, statistic=s_, bins=4)
        out += list(r.statistic)
    r = st.binned_statistic(x, y, bins=[1.0, 3.0, 4.5, 7.0])
    out += list(r.statistic) + [float(v) for v in r.binnumber]
    r = st.binned_statistic(x, y, bins=3, range=(2.0, 6.0))
    out += list(r.statistic) + list(r.bin_edges) + [float(v) for v in r.binnumber]
    assert close(out, bs)
    r2 = st.binned_statistic_2d(x, y, B[:12], statistic='mean', bins=3)
    assert close(list(r2.statistic.ravel()) + list(r2.x_edge) + list(r2.y_edge) + [float(v) for v in r2.binnumber], bs2)
    r3 = st.binned_statistic_dd(np.vstack([x, y]).T, B[:12], statistic='sum', bins=2)
    assert close(list(r3.statistic.ravel()) + [float(v) for v in r3.binnumber], bsd)
    out = []
    out += [st.weightedtau(x, y).statistic]
    out += [st.weightedtau(np.round(x), np.round(y)).statistic]
    out += [st.weightedtau(x, y, additive=False).statistic]
    out += [st.weightedtau(x, y, rank=False).statistic]
    out += [st.weightedtau(B, B[::-1] ** 2).statistic]
    assert close(out, wt)
test_kde_binned_wtau()
